import{_ as e,a as o,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Catalog Attribute Options — Create / Update / Delete","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-attribute-option-create","title":"Create Attribute Option","description":"Adds a new option to a `select`, `multiselect`, or `checkbox` attribute. Returns the full updated attribute detail.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/attributes/12/options\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"admin_name\\": \\"Wool\\",\\n    \\"sort_order\\": 2,\\n    \\"translations\\": {\\n      \\"en\\": { \\"label\\": \\"Wool\\" },\\n      \\"fr\\": { \\"label\\": \\"Laine\\" }\\n    }\\n  }\'\\n","variables":"attributeId=12\\n","response":"{\\n  \\"id\\": 12,\\n  \\"code\\": \\"material\\",\\n  \\"type\\": \\"select\\",\\n  \\"options\\": [\\n    { \\"id\\": 45, \\"adminName\\": \\"Wool\\", \\"sortOrder\\": 2 }\\n  ]\\n}\\n","commonErrors":[{"error":"Unsupported attribute type (422)","cause":"The attribute\'s `type` is not `select`, `multiselect`, or `checkbox`","solution":"Options can only be attached to option-bearing types"},{"error":"Validation (422)","cause":"`admin_name` missing","solution":"Provide `admin_name`"},{"error":"Not Found (404)","cause":"Unknown attribute id","solution":"Verify the attribute id"},{"error":"Unauthorized (401)","cause":"Missing or invalid admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]},{"id":"admin-catalog-attribute-option-update","title":"Update Attribute Option","description":"Partially update an existing option. Only supplied fields are changed; translations merge per locale.","query":"curl -X PUT \\"https://your-domain.com/api/admin/catalog/attributes/12/options/45\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"admin_name\\": \\"Merino Wool\\",\\n    \\"sort_order\\": 1,\\n    \\"translations\\": {\\n      \\"en\\": { \\"label\\": \\"Merino Wool\\" },\\n      \\"fr\\": { \\"label\\": \\"Laine Mérinos\\" }\\n    }\\n  }\'\\n","variables":"attributeId=12\\noptionId=45\\n","response":"{\\n  \\"id\\": 12,\\n  \\"code\\": \\"material\\",\\n  \\"type\\": \\"select\\"\\n}\\n"},{"id":"admin-catalog-attribute-option-delete","title":"Delete Attribute Option","description":"Removes an option. Refused (HTTP 409) when one or more products still reference the option.","query":"curl -X DELETE \\"https://your-domain.com/api/admin/catalog/attributes/12/options/45\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","variables":"attributeId=12\\noptionId=45\\n","response":"{\\n  \\"message\\": \\"Attribute option deleted successfully.\\"\\n}\\n","commonErrors":[{"error":"Option in use (409)","cause":"One or more products still reference this option in their attribute values","solution":"Reassign the products to a different option first, then retry"},{"error":"Not Found (404)","cause":"Unknown attribute or option id","solution":"Verify the ids"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/attributes/attribute-options.md","filePath":"api/rest-api/admin/catalog/attributes/attribute-options.md","lastUpdated":1787725411000}'),n={name:"api/rest-api/admin/catalog/attributes/attribute-options.md"};function i(r,t,s,l,c,p){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="catalog-attribute-options-—-create-update-delete" tabindex="-1">Catalog Attribute Options — Create / Update / Delete <a class="header-anchor" href="#catalog-attribute-options-—-create-update-delete" aria-label="Permalink to &quot;Catalog Attribute Options — Create / Update / Delete&quot;">​</a></h1><p>CRUD for individual options on <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> attributes. Options for other attribute types do not exist (the attribute payload returns <code>options: null</code>).</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/attributes/{attributeId}/options</code></td><td>POST</td><td>Add a new option</td></tr><tr><td><code>/api/admin/catalog/attributes/{attributeId}/options/{optionId}</code></td><td>PUT</td><td>Partially update an option</td></tr><tr><td><code>/api/admin/catalog/attributes/{attributeId}/options/{optionId}</code></td><td>DELETE</td><td>Remove an option</td></tr></tbody></table><p>Both <code>{attributeId}</code> and <code>{optionId}</code> are constrained to digits (<code>\\d+</code>).</p><h2 id="request-body-—-create-update" tabindex="-1">Request body — Create / Update <a class="header-anchor" href="#request-body-—-create-update" aria-label="Permalink to &quot;Request body — Create / Update&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>admin_name</code></td><td>string</td><td>yes (create) / no (update)</td><td>Internal admin label.</td></tr><tr><td><code>sort_order</code></td><td>integer</td><td>no</td><td>Display order.</td></tr><tr><td><code>swatch_value</code></td><td>string|null</td><td>no</td><td>Hex color for <code>color</code> swatches, image path for <code>image</code> swatches, display text for <code>text</code> swatches.</td></tr><tr><td><code>translations</code></td><td>object</td><td>no</td><td>Map of locale → <code>{ label }</code>. Merges per-locale on update.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><ul><li><strong>Create</strong> — <code>201 Created</code> with the full attribute detail (same shape as <code>GET /api/admin/catalog/attributes/{id}</code>).</li><li><strong>Update</strong> — <code>200 OK</code> with the full attribute detail.</li><li><strong>Delete</strong> — <code>200 OK</code> with <code>{ &quot;message&quot;: &quot;...&quot; }</code>.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>Unknown <code>attributeId</code> or <code>optionId</code></td></tr><tr><td><code>409 Conflict</code></td><td>(delete only) Option is referenced by product attribute values</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>(create) Attribute type does not support options, or <code>admin_name</code> missing</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The delete-409 message names the dependency count: <code>This option is used by N product(s) and cannot be deleted.</code></li><li>For bulk attribute changes, supply the full <code>options</code> array on the <a href="/api/rest-api/admin/catalog/attributes/attributes-update.html">Update Attribute</a> endpoint — that replaces the whole option set in one call.</li></ul>',13)]))}const b=e(n,[["render",i]]);export{h as __pageData,b as default};
